import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:mirthmix/content/content.dart';
import 'package:mirthmix/game/random.dart';
import 'package:mirthmix/game/wyr_engine.dart';

/// Replays the vectors generated by the TypeScript engine (packages/game-engine) and checks the
/// Dart port produces identical results.
void main() {
  final vectors = jsonDecode(
    File('../../packages/game-engine/test-vectors/would-you-rather.json').readAsStringSync(),
  ) as Map<String, dynamic>;
  final items = (vectors['items'] as List<dynamic>).map((i) => WyrItem.fromJson(i as Map<String, dynamic>)).toList();

  group('rng', () {
    for (final v in (vectors['rng'] as List<dynamic>).cast<Map<String, dynamic>>()) {
      test('seed ${v['seed']}', () {
        final next = createRng(v['seed'] as int);
        expect([for (var i = 0; i < 6; i++) next()], v['values']);
      });
    }
  });

  group('shuffle', () {
    for (final v in (vectors['shuffle'] as List<dynamic>).cast<Map<String, dynamic>>()) {
      test('seed ${v['seed']}', () {
        expect(seededShuffle((v['input'] as List<dynamic>).cast<String>(), v['seed'] as int), v['output']);
      });
    }
  });

  group('would you rather', () {
    for (final v in (vectors['wyr'] as List<dynamic>).cast<Map<String, dynamic>>()) {
      test(v['name'] as String, () {
        final config = WyrConfig.fromJson(v['config'] as Map<String, dynamic>);
        var state = createWyrSession(buildPool(items, config.categoryIds), config);
        for (final a in (v['actions'] as List<dynamic>).cast<Map<String, dynamic>>()) {
          state = reduceWyr(state, switch (a['type']) {
            'vote' => Vote(Side.values.byName(a['side'] as String)),
            'undo' => const Undo(),
            'reveal' => const Reveal(),
            'next' => const Next(),
            'skip' => const SkipQuestion(),
            _ => throw StateError('unknown action ${a['type']}'),
          });
        }
        final expected = v['expected'] as Map<String, dynamic>;
        expect(state.order, expected['order']);
        expect(state.totalRounds, expected['totalRounds']);
        expect(state.status.name, expected['status']);
        expect(state.skips, expected['skips']);
        expect(state.rounds.map((r) => r.toJson()).toList(), expected['rounds']);
        expect(state.current?.toJson(), expected['current']);
        expect(wyrResults(state).toJson(), expected['results']);
      });
    }
  });
}
